  'cron-explainer': {
    metaTitle: 'cron式 解説ツール — 日本語訳＋次の実行時刻',
    metaDescription:
      'cronの5フィールド（分 時 日 月 曜日）を日本語で解説し、次の7回の実行時刻も表示。*/5は5分ごと、0 9 * * 1-5は平日9時など。範囲(a-b)・ステップ(*/n)・別名(JAN-DEC, MON-SUN)に対応します。',
    intro:
      'cron式（分 時 日 月 曜日の5フィールド）を日本語の言葉に翻訳し、次の7回の実行予定時刻まで表示するツールです。例えば「*/5 * * * *」は「5分ごと」、「0 9 * * 1-5」は「平日の9:00」と解釈されます。各フィールドが何個の値に展開されるかも一覧でき、誤った式はエラーで指摘します。',
    features: [
      '5フィールドのcron式を日本語の説明文に変換します（例: 0 9 * * 1-5 → 平日 09:00）。',
      '現在時刻を基準に、次の7回の実行予定時刻をローカルタイムで表示します。',
      '範囲(1-5)・ステップ(*/5)・リスト(1,3,5)・別名(JAN-DEC, SUN-SAT)に対応します。',
      '日と曜日が両方指定された場合はOR結合（どちらか一致で実行）という標準cronの挙動に従います。',
      '「5分ごと」「平日業務時間」などのプリセットをワンクリックで挿入できます。',
    ],
    steps: [
      {
        title: 'cron式を入力',
        body: '「分 時 日 月 曜日」の順に5つの値を入力します。例: */5 * * * *（5分ごと）、0 9 * * 1-5（平日9時）。プリセットボタンから選んで埋めることもできます。',
      },
      {
        title: '日本語の解釈を確認',
        body: '式の意味が日本語で表示され、各フィールドの展開値の個数も並びます。例えば「0 0 1 * *」なら「毎月1日 00:00」と解釈されます。',
      },
      {
        title: '次の実行時刻を確認',
        body: '下部に次の7回の実行予定時刻がローカルタイムで一覧表示されます。設定したスケジュールが意図通りか、実際の日時で検証できます。',
      },
    ],
    faqs: [
      {
        q: '曜日の0と7はどちらも日曜日ですか？',
        a: 'はい。標準のUnix cronでは曜日フィールドの0が日曜、1が月曜…6が土曜で、7も日曜として扱われます（0と7が同じ）。本ツールも7を日曜（0）に正規化します。SUN・MONなどの英字別名も使えます。',
      },
      {
        q: '「*/5」のようなスラッシュは何を意味しますか？',
        a: 'スラッシュはステップ（間隔）を表します。分フィールドの */5 は「5分ごと」（0, 5, 10, …, 55分）の意味です。*/15 なら15分ごと、時フィールドの */2 なら2時間ごとになります。0を指定するとエラーになります。',
      },
      {
        q: '日（3番目）と曜日（5番目）を両方指定するとどうなりますか？',
        a: '標準cronでは、日と曜日が両方とも「*」以外で指定された場合はOR結合になり、どちらかの条件に一致した日に実行されます。例えば「0 0 1 * 1」は「毎月1日」または「毎週月曜」に実行されます。片方が*の場合はAND（通常の絞り込み）です。',
      },
    ],
  },

